//! Hold presentation physics while a ragdoll sample is captured from each view.

use super::*;
use adventuresim_tactical_core::avian3d::prelude::{Physics, PhysicsTime};

#[derive(Default, Resource)]
pub(super) struct CapturePhysicsPause {
    owns_pause: bool,
    sample_held: bool,
}

pub(super) fn synchronize_capture_physics(
    sequence: Res<CaptureSequence>,
    mut ownership: ResMut<CapturePhysicsPause>,
    mut physics: ResMut<Time<Physics>>,
) {
    if ownership.sample_held && (!sequence.applied || !sequence.admission.is_open()) {
        if ownership.owns_pause {
            physics.unpause();
        }
        ownership.sample_held = false;
        ownership.owns_pause = false;
    }
}

pub(super) fn hold_capture_physics_before_sampling(
    mut sequence: ResMut<CaptureSequence>,
    mut ownership: ResMut<CapturePhysicsPause>,
    mut physics: ResMut<Time<Physics>>,
) {
    let first_ragdoll_view = sequence.applied
        && sequence.view_index == 0
        && !sequence.capture_in_flight
        && sequence
            .plan
            .get(sequence.index)
            .is_some_and(|frame| frame.scenario.is(ScenarioId::FullRagdoll));
    if !first_ragdoll_view || ownership.sample_held
        || sequence.settled.saturating_add(1) < required_settle_frames(&sequence)
    {
        return;
    }
    ownership.owns_pause = !physics.is_paused();
    if ownership.owns_pause {
        physics.pause();
    }
    ownership.sample_held = true;
    // Render the paused physics state before taking the first baseline view.
    sequence.settled = 0;
}

pub(super) fn required_settle_frames(sequence: &CaptureSequence) -> u32 {
    if sequence.index == 0 {
        sequence.settle_frames.max(60)
    } else {
        sequence.settle_frames.max(2)
    }
}

